define(['core/ajax'],function(Ajax){return{init:function(cmid,savedMessage,failedMessage){const container=document.getElementById('ef-sections');const addResultSelect=document.getElementById('addsectionresult');const addCollagePreview=document.querySelector('.ef-add-collage-preview');if(addResultSelect&&addCollagePreview){const toggleAddCollagePreview=function(){addCollagePreview.style.display=addResultSelect.value==='collage:0'?'':'none';};addResultSelect.addEventListener('change',toggleAddCollagePreview);toggleAddCollagePreview();}document.querySelectorAll('.ef-confirm-form').forEach(function(form){form.addEventListener('submit',function(event){const message=form.getAttribute('data-confirm-message')||'';if(message&&!window.confirm(message)){event.preventDefault();}});});if(!container){return;}let dragged=null;let originalOrder='';let saveTimer=null;const currentOrder=function(){return Array.from(container.querySelectorAll('.ef-section-card')).map(function(card){return card.getAttribute('data-section-id');}).filter(Boolean).join(',');};const showOrderStatus=function(message,isError){let status=document.getElementById('ef-order-status');if(!status){status=document.createElement('div');status.id='ef-order-status';status.className='ef-order-status';container.parentNode.insertBefore(status,container);}status.textContent=message;status.classList.toggle('ef-order-status-error',!!isError);status.classList.add('ef-order-status-visible');window.setTimeout(function(){status.classList.remove('ef-order-status-visible');},2500);};const postOrder=function(){const order=currentOrder();if(!order||order===originalOrder){return;}originalOrder=order;if(!cmid){return;}Ajax.call([{methodname:'mod_experiencefinder_reorder_sections',args:{cmid:cmid,order:order}}])[0].then(function(result){if(!result||!result.status){throw new Error('Order save failed');}showOrderStatus(savedMessage,false);}).catch(function(){showOrderStatus(failedMessage,true);});};const queuePostOrder=function(){if(saveTimer){window.clearTimeout(saveTimer);}saveTimer=window.setTimeout(postOrder,150);};originalOrder=currentOrder();container.addEventListener('dragstart',function(event){const card=event.target.closest('.ef-section-card');if(!card){return;}dragged=card;originalOrder=currentOrder();card.classList.add('ef-dragging');event.dataTransfer.effectAllowed='move';event.dataTransfer.setData('text/plain',card.getAttribute('data-section-id'));});container.addEventListener('dragend',function(){if(dragged){dragged.classList.remove('ef-dragging');}Array.from(container.querySelectorAll('.ef-drop-target')).forEach(function(el){el.classList.remove('ef-drop-target');});dragged=null;queuePostOrder();});container.addEventListener('dragover',function(event){if(!dragged){return;}const card=event.target.closest('.ef-section-card');if(!card||card===dragged){return;}event.preventDefault();const rect=card.getBoundingClientRect();const after=(event.clientY-rect.top)>rect.height/2;card.classList.add('ef-drop-target');if(after){card.after(dragged);}else{card.before(dragged);}});container.addEventListener('dragleave',function(event){const card=event.target.closest('.ef-section-card');if(card){card.classList.remove('ef-drop-target');}});container.addEventListener('drop',function(event){if(!dragged){return;}event.preventDefault();queuePostOrder();});}};});
